import json,base64,urllib.parse,pathlib
d='products/services/tender-offer-test/search-exposure/'
x=json.loads(pathlib.Path(d+'extract.json').read_text())
def dec(h):
  q=urllib.parse.parse_qs(urllib.parse.urlparse(h).query).get('u',[''])[0]
  if q.startswith('a1'):
    s=q[2:];s+='='*(-len(s)%4)
    try: return base64.urlsafe_b64decode(s).decode('utf-8','replace')
    except Exception: return None
  return h
qs=[]
for q in x['queries']:
  urls=[{'url':dec(r['href']),'title':r['title']} for r in q['results']]
  ours=[u for u in urls if u['url'] and 'global-land.workers.dev' in u['url']]
  qs.append({'query':q['query'],'fetch_task':q['fetch_task'],'sha256':q['sha256'],'result_count_parsed':len(urls),'results':urls,'globalland_result_listed':bool(ours),'note_mentions':'page-level counts of global-land strings include the echoed query text and are not listings','captcha_or_challenge_string_present':q['captcha_or_challenge']})
listed=any(q['globalland_result_listed'] for q in qs)
res={'mission':'TENDER-OFFER-SEARCH-EXPOSURE','observed_at':'2026-11-12 (UTC, FETCH TASK-179446716111..113)','engine':'Bing HTML, unauthenticated FETCH; results may be personalised/region-dependent','queries':qs,'finding':('A GlobalLand page was listed' if listed else 'No GlobalLand page appeared in the top parsed results of any of the three queries; the exact-hostname query returned unrelated results (Bing ignored the quoted hostname).'),'limits':['Three Bing queries only; not evidence about indexing generally, other engines, clicks, buyers or revenue','A challenge/captcha string appears in the HTML; results still parsed but may be degraded'],'exposure_action':('None executable now. Prior IndexNow submission for the refresh/calendar was INTERRUPTED (L234) and must not be blindly resubmitted; the pending hash-correction release (digest d211ba68..., awaiting independent review) is the next legitimate change occasion for one IndexNow notification of the updated URL.' if not listed else 'n/a'),'reconsideration_trigger':'Approved deployment of digest d211ba68... (new notification occasion) or the host journal showing the INTERRUPTED IndexNow request was never sent.','demand':'UNKNOWN (0 classified, 5 unclassified feedback sources); no revenue'}
pathlib.Path(d+'result.json').write_text(json.dumps(res,indent=1,ensure_ascii=False))
for q in qs: print(q['query'],q['globalland_result_listed'],[u['url'][:70] for u in q['results'][:6]])
print(res['finding'])
